DECLARE bad integer;
BEGIN
  SELECT count(*) INTO bad FROM blog_posts WHERE jsonb_typeof(content) <> 'object';
  IF bad > 0 THEN RAISE EXCEPTION 'blog_posts: % row(s) with a non-object content', bad; END IF;

  -- All six languages this time, which is the omission 071 made.
  SELECT count(*) INTO bad FROM blog_posts, unnest(ARRAY['en','ca','es','fr','de','da']) l
   WHERE content->>l ~ '[0-9](\s+–|–\s+)[.,]?[0-9]';
  IF bad > 0 THEN RAISE EXCEPTION 'blog_posts: % body(ies) with a spaced en dash in a range', bad; END IF;
END $$;

